/// <summary>
/// Method is used to populate <c>UPSAllowedValuesListTemp</c> temporary tables with values from Set parameter
/// </summary>
/// <param name = "_valuesSet">The value set to display.</param>
/// <param name = "_hasDescription">True if the value has a text description field.</param>
/// <returns>Temp table placeholder.</returns>
public static UPSAllowedValuesListTemp populate(Set _valuesSet, boolean _hasDescription = false)
{
    UPSAllowedValuesListTemp table;
    SetEnumerator            se;

    se = _valuesSet.getEnumerator();

    while (se.MoveNext())
    {
        table.clear();
        table.initValue();

        if (_hasDescription)
        {
            UPSPricingAttributeAllowedValuesObject valueObject = se.current();
            table.Value = valueObject.getValueName();
            table.Description = valueObject.getValueDescription();
        } 
        else 
        {
            table.Value = se.current();
        }

        table.insert();
    }

    return table;
}
